const GP_API =
  "https://apis.sandbox.globalpay.com/ucp";

const GP_VERSION =
  "2021-03-22";


// =================================
// SHA-512 HELPER
// =================================

async function sha512(value) {
  const data =
    new TextEncoder().encode(
      value
    );

  const hashBuffer =
    await crypto.subtle.digest(
      "SHA-512",
      data
    );

  return Array.from(
    new Uint8Array(
      hashBuffer
    )
  )
    .map(
      byte =>
        byte
          .toString(16)
          .padStart(2, "0")
    )
    .join("");
}


// =================================
// ACCESS TOKEN
// =================================

export async function getAccessToken(
  env
) {
  const nonce =
    new Date().toISOString();

  const secret =
    await sha512(
      nonce +
      env.GP_APP_KEY
    );


  const response =
    await fetch(
      `${GP_API}/accesstoken`,
      {
        method:
          "POST",

        headers: {
          "Content-Type":
            "application/json",

          "X-GP-Version":
            GP_VERSION
        },

        body:
          JSON.stringify({
            app_id:
              env.GP_APP_ID,

            nonce:
              nonce,

            secret:
              secret,

            grant_type:
              "client_credentials"
          })
      }
    );


  const data =
    await response.json();


  if (!response.ok) {
    console.error(
      "Global Payments authentication failed:",
      data
    );

    throw new Error(
      "Unable to authenticate with Global Payments."
    );
  }


  if (!data.token) {
    console.error(
      "Global Payments token missing:",
      data
    );

    throw new Error(
      "Global Payments did not return an access token."
    );
  }


  return data;
}


// =================================
// CREATE HOSTED PAYMENT PAGE
// =================================

export async function createHostedPaymentPage(
  env,
  {
    amount,
    currency,
    reference,
    email,
    customerName,
    paymentReturnUrl
  }
) {
  const tokenData =
    await getAccessToken(
      env
    );

  const accessToken =
    tokenData.token;


	const returnUrlObject =
	  new URL(
		paymentReturnUrl
	  );

	returnUrlObject.searchParams.set(
	  "reference",
	  reference
	);

	const returnUrl =
	  returnUrlObject.toString();


  const response =
    await fetch(
      `${GP_API}/links`,
      {
        method:
          "POST",

        headers: {
          "Content-Type":
            "application/json",

          "Accept":
            "application/json",

          "Authorization":
            `Bearer ${accessToken}`,

          "X-GP-Version":
            GP_VERSION
        },

        body:
          JSON.stringify({
            account_name:
              "transaction_processing_hpp",

            type:
              "HOSTED_PAYMENT_PAGE",

            name:
              "Jekyll Commerce Checkout",

            description:
              "Online store purchase",

            usage_mode:
              "SINGLE",

            reference:
              reference,

            payer: {
              email:
                email
            },

            order: {
              amount:
                String(
                  amount
                ),

              currency:
                currency,

              reference:
                reference,

              transaction_configuration: {
                channel:
                  "CNP",

                country:
                  "US",

                capture_mode:
                  "AUTO",

                allowed_payment_methods: [
                  "CARD"
                ]
              }
            },

            payment_method_configuration: {
              authentication: {
                preference:
                  "CHALLENGE_PREFERRED"
              }
            },

            notifications: {
              return_url:
                returnUrl
            }
          })
      }
    );


  const data =
    await response.json();


  if (!response.ok) {
    console.error(
      "Unable to create HPP:",
      {
        status:
          response.status,

        response:
          data
      }
    );

    throw new Error(
      "Unable to create hosted checkout."
    );
  }


  if (!data.url) {
    console.error(
      "Global Payments HPP URL missing:",
      data
    );

    throw new Error(
      "Global Payments did not return a checkout URL."
    );
  }


  return data;
}


// =================================
// SLEEP HELPER
// =================================

function wait(milliseconds) {
  return new Promise(
    resolve =>
      setTimeout(
        resolve,
        milliseconds
      )
  );
}


// =================================
// GET / VERIFY TRANSACTION
// =================================

export async function getTransaction(
  env,
  transactionId,
  {
    attempts = 4,
    delayMs = 750
  } = {}
) {
  if (!transactionId) {
    throw new Error(
      "Transaction ID is required."
    );
  }


  let lastTransaction =
    null;


  for (
    let attempt = 1;
    attempt <= attempts;
    attempt++
  ) {
    const tokenData =
      await getAccessToken(
        env
      );

    const accessToken =
      tokenData.token;


    const response =
      await fetch(
        `${GP_API}/transactions/${encodeURIComponent(
          transactionId
        )}`,
        {
          method:
            "GET",

          headers: {
            "Accept":
              "application/json",

            "Authorization":
              `Bearer ${accessToken}`,

            "X-GP-Version":
              GP_VERSION
          }
        }
      );


    const data =
      await response.json();


    if (!response.ok) {
      console.error(
        "Unable to verify GP transaction:",
        {
          transactionId:
            transactionId,

          attempt:
            attempt,

          httpStatus:
            response.status,

          response:
            data
        }
      );


      throw new Error(
        "Unable to verify transaction with Global Payments."
      );
    }


    lastTransaction =
      data;


    console.log(
      "GP TRANSACTION LOOKUP",
      {
        transactionId:
          transactionId,

        attempt:
          attempt,

        status:
          data.status,

        amount:
          data.amount,

        currency:
          data.currency,

        reference:
          data.reference
      }
    );


    // -----------------------------
    // FINAL STATES
    // -----------------------------

    if (
      data.status ===
        "CAPTURED" ||
      data.status ===
        "DECLINED" ||
      data.status ===
        "REVERSED"
    ) {
      return data;
    }


    // -----------------------------
    // STILL PROCESSING
    // -----------------------------

    if (
      attempt <
      attempts
    ) {
      console.log(
        "GP transaction has not settled yet. Retrying...",
        {
          transactionId:
            transactionId,

          currentStatus:
            data.status,

          nextAttempt:
            attempt + 1
        }
      );


      await wait(
        delayMs
      );
    }
  }


  console.error(
    "GP transaction did not reach a final state:",
    {
      transactionId:
        transactionId,

      attempts:
        attempts,

      lastStatus:
        lastTransaction?.status,

      lastAmount:
        lastTransaction?.amount,

      lastReference:
        lastTransaction?.reference
    }
  );


  throw new Error(
    "Global Payments transaction did not reach a final state in time."
  );
}