const DEFAULT_STORE_CONFIG = {
  name:
    "Jekyll Commerce",

  currency:
    "USD",

  storefrontOrigin:
    "https://chew-max.github.io",

  storefrontBasePath:
    "/jekyll-commerce-starter",

  successUrl:
    "https://chew-max.github.io/jekyll-commerce-starter/checkout/success/",

  failedUrl:
    "https://chew-max.github.io/jekyll-commerce-starter/checkout/failed",

  paymentReturnUrl:
    "https://jekyll-commerce-api.mth-commerce.workers.dev/api/payment-return",

  maxQuantity:
    10,

  fulfillmentProvider:
    "printify",

  emailProvider:
    "resend",

  emailFrom:
    "Jekyll Commerce <onboarding@resend.dev>"
};


function positiveInteger(
  value,
  fallback
) {
  const parsed =
    Number.parseInt(
      String(value ?? ""),
      10
    );

  if (
    !Number.isInteger(parsed) ||
    parsed < 1
  ) {
    return fallback;
  }

  return parsed;
}


export function getStoreConfig(
  env = {}
) {
  return {
    name:
      env.STORE_NAME ||
      DEFAULT_STORE_CONFIG.name,

    currency:
      env.STORE_CURRENCY ||
      DEFAULT_STORE_CONFIG.currency,

    storefrontOrigin:
      env.STOREFRONT_ORIGIN ||
      DEFAULT_STORE_CONFIG.storefrontOrigin,

    storefrontBasePath:
      env.STOREFRONT_BASE_PATH ||
      DEFAULT_STORE_CONFIG.storefrontBasePath,

    successUrl:
      env.STORE_SUCCESS_URL ||
      DEFAULT_STORE_CONFIG.successUrl,

    failedUrl:
      env.STORE_FAILED_URL ||
      DEFAULT_STORE_CONFIG.failedUrl,

    paymentReturnUrl:
      env.PAYMENT_RETURN_URL ||
      DEFAULT_STORE_CONFIG.paymentReturnUrl,

    maxQuantity:
      positiveInteger(
        env.STORE_MAX_QUANTITY,
        DEFAULT_STORE_CONFIG.maxQuantity
      ),

    fulfillmentProvider:
      env.FULFILLMENT_PROVIDER ||
      DEFAULT_STORE_CONFIG.fulfillmentProvider,

    emailProvider:
      env.EMAIL_PROVIDER ||
      DEFAULT_STORE_CONFIG.emailProvider,

    emailFrom:
      env.STORE_EMAIL_FROM ||
      DEFAULT_STORE_CONFIG.emailFrom
  };
}


export {
  DEFAULT_STORE_CONFIG
};